// measureTestData is the exact wire bits writeTestData would produce for value —
// trusted like the writer; static runs fold to literals at generation time.
int measureTestData(TestData value) {
  var bits = 0;
  bits += 54;
  bits += value.itemsCount * 8;
  bits += 355;
  bits += (8 - (bits & 7)) & 7;
  bits += 144;
  bits += (8 - (bits & 7)) & 7;
  bits += value.textLength * 8;
  return bits;
}

// type CompressedProbe
final class CompressedProbe {
  // compressed float [0.0, 10.0] @ 0.01
  double boundary = 0.0;
  // compressed float [-5.0, 5.0] @ 0.001
  double offset = 0.0;
}

// compressedProbeMaxBits is the longest wire path; align pads at worst case (SPEC §6.1).
// compressedProbeMaxBytes is rounded up to the 8-byte write-buffer granularity.
const int compressedProbeMaxBits = 24;
const int compressedProbeMaxBytes = 8;

// The §5 zero form: all-zero storage; specified defaults live only in
// construction.
void zeroCompressedProbe(CompressedProbe value) {
  value.boundary = 0.0;
  value.offset = 0.0;
}

// writeCompressedProbe packs value into view — the trusted writer (contracts asserted,
// compiled out without --enable-asserts). The buffer behind view must hold
// compressedProbeMaxBytes. Returns the bytes written, or -1 when a count is outside its
// wire range, which is refused in every build (SPEC §4.6).
int writeCompressedProbe(CompressedProbe value, ByteData view) {
  assert(view.lengthInBytes % 8 == 0);
  assert(view.lengthInBytes >= compressedProbeMaxBytes);
  var scratch = 0;
  var scratchBits = 0;
  var wordIndex = 0;
  var v = 0;
  {
    final x = _fround(value.boundary);
    assert(x.isFinite);
    var n = _fround(_fround(x - 0.0) / 10.0);
    if (!(n >= 0.0)) {
      n = 0.0;
    } else if (!(n <= 1.0)) {
      n = 1.0;
    }
    v = _fround(_fround(n * 1000.0) + 0.5).floor();
  }
  scratch |= v << scratchBits;
  scratchBits += 10;
  if (scratchBits >= 64) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
    wordIndex++;
    scratchBits -= 64;
    scratch = v >>> (10 - scratchBits);
  }
  {
    final x = _fround(value.offset);
    assert(x.isFinite);
    var n = _fround(_fround(x - -5.0) / 10.0);
    if (!(n >= 0.0)) {
      n = 0.0;
    } else if (!(n <= 1.0)) {
      n = 1.0;
    }
    v = _fround(_fround(n * 10000.0) + 0.5).floor();
  }
  scratch |= v << scratchBits;
  scratchBits += 14;
  if (scratchBits >= 64) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
    wordIndex++;
    scratchBits -= 64;
    scratch = v >>> (14 - scratchBits);
  }
  if (scratchBits != 0) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
  }
  return wordIndex * 8 + ((scratchBits + 7) >>> 3);
}

// readCompressedProbe decodes value from the first numBits of view — the family read
// verdict: false rejects the wire (bounds, ranges, wire constants, padding);
// hostile bytes never throw. No slack past the payload is required.
bool readCompressedProbe(CompressedProbe value, ByteData view, int numBits) {
  if (numBits > view.lengthInBytes * 8) {
    return false; // the payload cannot exceed the buffer behind view
  }
  // the final 64-bit window, assembled once so every load stays inside
  // the buffer (serialize.dart's own no-slack reader stance)
  var tailBase = view.lengthInBytes - 8;
  var tailWord = 0;
  if (tailBase >= 0) {
    tailWord = view.getUint64(tailBase, Endian.little);
  } else {
    tailBase = 0;
    for (var i = view.lengthInBytes - 1; i >= 0; i--) {
      tailWord = (tailWord << 8) | view.getUint8(i);
    }
  }
  var bitsRead = 0;
  var window = 0;
  var v = 0;
  if (bitsRead + 24 > numBits) {
    return false;
  }
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0x3ff;
  bitsRead += 10;
  if (v > 1000) {
    return false; // headroom above the quantum count is refused
  }
  value.boundary = _fround(
    _fround(_fround(_fround(v.toDouble()) / 1000.0) * 10.0) + 0.0,
  );
  v = (window >>> 10) & 0x3fff;
  bitsRead += 14;
  if (v > 10000) {
    return false; // headroom above the quantum count is refused
  }
  value.offset = _fround(
    _fround(_fround(_fround(v.toDouble()) / 10000.0) * 10.0) + -5.0,
  );
